create table if not exists public.customer_auth_rate_limits(key_hash text primary key,attempts int not null default 0,window_started_at timestamptz not null default now(),blocked_until timestamptz,updated_at timestamptz not null default now());alter table public.customer_auth_rate_limits enable row level security;
create or replace function public.consume_customer_auth_rate_limit(p_key text) returns boolean language plpgsql security definer set search_path=public as $$declare r public.customer_auth_rate_limits;nowv timestamptz:=now();begin if length(p_key)<32 then return false;end if;insert into public.customer_auth_rate_limits(key_hash,attempts) values(p_key,1) on conflict(key_hash) do update set attempts=case when customer_auth_rate_limits.window_started_at<nowv-interval '15 minutes' then 1 else customer_auth_rate_limits.attempts+1 end,window_started_at=case when customer_auth_rate_limits.window_started_at<nowv-interval '15 minutes' then nowv else customer_auth_rate_limits.window_started_at end,blocked_until=case when customer_auth_rate_limits.window_started_at>=nowv-interval '15 minutes' and customer_auth_rate_limits.attempts+1>12 then nowv+interval '15 minutes' else customer_auth_rate_limits.blocked_until end,updated_at=nowv returning * into r;return r.blocked_until is null or r.blocked_until<=nowv;end$$;revoke all on function public.consume_customer_auth_rate_limit(text) from public,anon;grant execute on function public.consume_customer_auth_rate_limit(text) to authenticated,anon;
insert into public.admin_help_items(help_key,title_fa,body_fa,warning_fa,title_en,body_en,warning_en,active) values
('customers.auth','ورود و ثبت‌نام مشتری','ورود مشتری از ورود مدیران جداست. مشتری با ایمیل و رمز حساب می‌سازد، در صورت فعال بودن تأیید ایمیل آن را تأیید می‌کند و سپس به سفارش‌ها و آدرس‌های همان فروشگاه دسترسی دارد. بازیابی رمز نیز پیام یکسانی برای ایمیل موجود و ناموجود نشان می‌دهد.','هیچ‌وقت صفحه ورود مشتری را به دسترسی مدیریت متصل نکن. خطاها نباید وجود یا عدم وجود یک ایمیل را افشا کنند و محدودیت تلاش ورود باید فعال بماند.','Customer sign-in and registration','Customer authentication is separate from administrator authentication. Customers create an email/password account, confirm email when enabled, then access their own orders and addresses for that store. Password recovery returns the same response whether an email exists or not.','Never connect customer sign-in to administrative access. Errors must not reveal whether an email exists, and authentication rate limiting must remain enabled.',true)
on conflict(help_key) do update set title_fa=excluded.title_fa,body_fa=excluded.body_fa,warning_fa=excluded.warning_fa,title_en=excluded.title_en,body_en=excluded.body_en,warning_en=excluded.warning_en,active=true;
